import{_ as l,C as p,o as a,c as h,j as t,a as o,b as r,w as d,E as c,af as n,a6 as i}from"./chunks/framework.DIp0zHSV.js";const A=JSON.parse('{"title":"HA Integration Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ha-integration.md","filePath":"architecture/ha-integration.md","lastUpdated":1791165399000}'),u={name:"architecture/ha-integration.md"};function g(_,e,m,y,b,f){const s=p("Mermaid");return a(),h("div",null,[e[3]||(e[3]=t("h1",{id:"ha-integration-architecture",tabindex:"-1"},[o("HA Integration Architecture "),t("a",{class:"header-anchor",href:"#ha-integration-architecture","aria-label":'Permalink to "HA Integration Architecture"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("LCARdS ships as a "),t("strong",null,"HACS Integration"),o(" ("),t("code",null,"custom_components/lcards/"),o("). This page covers the Python-side architecture: how the integration boots, what it registers in Home Assistant, and how it hands off to the JavaScript frontend.")],-1)),e[5]||(e[5]=t("hr",null,null,-1)),e[6]||(e[6]=t("h2",{id:"two-layer-architecture",tabindex:"-1"},[o("Two-Layer Architecture "),t("a",{class:"header-anchor",href:"#two-layer-architecture","aria-label":'Permalink to "Two-Layer Architecture"'},"​")],-1)),(a(),r(n,null,{default:d(()=>[c(s,{id:"mermaid-10",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20subgraph%20HA%5B%22Home%20Assistant%22%5D%0A%20%20%20%20%20%20%20%20subgraph%20Integration%5B%22custom_components%2Flcards%2F%20(Python)%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Init%5B%22__init__.py%5Cnasync_setup%20%2F%20async_setup_entry%5Cnasync_unload_entry%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Frontend%5B%22frontend.py%5CnStatic%20paths%20%2B%20JS%20injection%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20ConfigFlow%5B%22config_flow.py%5CnSetup%20flow%20%2B%20Options%20flow%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20WS%5B%22websocket_api.py%5Cnlcards%2F*%20WS%20commands%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Const%5B%22const.py%5CnDOMAIN%2C%20version%2C%20option%20keys%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20HTTP%5B%22HA%20HTTP%20server%22%5D%0A%20%20%20%20%20%20%20%20WSSrv%5B%22HA%20WebSocket%20server%22%5D%0A%20%20%20%20%20%20%20%20Lovelace%5B%22Lovelace%20resources%22%5D%0A%20%20%20%20%20%20%20%20Sidebar%5B%22Sidebar%20panel%20registry%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Browser%5B%22Browser%22%5D%0A%20%20%20%20%20%20%20%20lcards_js%5B%22lcards.js%5Cn(JS%20frontend%20bundle)%22%5D%0A%20%20%20%20%20%20%20%20IntSvc%5B%22IntegrationService%5Cnwindow.lcards.core.integrationService%22%5D%0A%20%20%20%20%20%20%20%20Cards%5B%22LCARdS%20Cards%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Init%20--%3E%7C%22register%20static%20paths%22%7C%20Frontend%0A%20%20%20%20Init%20--%3E%7C%22register%20WS%20commands%22%7C%20WS%0A%20%20%20%20Frontend%20--%3E%7C%22StaticPathConfig%20%C3%97%203%22%7C%20HTTP%0A%20%20%20%20Frontend%20--%3E%7C%22add_extra_js_url%22%7C%20lcards_js%0A%20%20%20%20Frontend%20--%3E%7C%22Lovelace%20resource%22%7C%20Lovelace%0A%20%20%20%20Init%20--%3E%7C%22async_register_built_in_panel%22%7C%20Sidebar%0A%20%20%20%20WS%20--%3E%20WSSrv%0A%0A%20%20%20%20lcards_js%20--%3E%20IntSvc%0A%20%20%20%20IntSvc%20--%3E%7C%22lcards%2Finfo%20WS%22%7C%20WSSrv%0A%20%20%20%20WSSrv%20--%3E%20WS%0A%20%20%20%20lcards_js%20--%3E%20Cards%0A%0A%20%20%20%20style%20Integration%20fill%3A%231c3c55%2Cstroke%3A%2337a6d1%2Ccolor%3A%23eee%0A%20%20%20%20style%20Browser%20fill%3A%232f3749%2Cstroke%3A%2352596e%2Ccolor%3A%23eee%0A%20%20%20%20style%20HA%20fill%3A%231e2229%2Cstroke%3A%232f3749%2Ccolor%3A%23eee%0A%20%20%20%20style%20lcards_js%20fill%3A%23e7442a%2Cstroke%3A%23ffb399%2Ccolor%3A%23fff%0A%20%20%20%20style%20IntSvc%20fill%3A%236d748c%2Cstroke%3A%23d2d5df%2Ccolor%3A%23fff%0A%20%20%20%20style%20Cards%20fill%3A%23e7442a%2Cstroke%3A%23ffb399%2Ccolor%3A%23fff%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=i('<hr><h2 id="python-component-files" tabindex="-1">Python Component Files <a class="header-anchor" href="#python-component-files" aria-label="Permalink to &quot;Python Component Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>__init__.py</code></td><td>Entry point: wires up static paths, JS injection, sidebar panel, storage init, WS commands, services, log level, and options update listener</td></tr><tr><td><code>frontend.py</code></td><td>Registers static HTTP paths and injects <code>lcards.js</code> (with <code>?log=</code> param) into every HA frontend session</td></tr><tr><td><code>config_flow.py</code></td><td>Initial setup flow (single-instance, no user input) + options flow (panel, log level, sidebar customisation)</td></tr><tr><td><code>websocket_api.py</code></td><td>Registers <code>lcards/info</code>, <code>lcards/subscribe</code>, and all <code>lcards/storage/*</code> WebSocket commands</td></tr><tr><td><code>media_source.py</code></td><td><code>MediaSource</code> platform: exposes bundled <code>images/</code>/<code>sounds/</code> as a browsable &quot;LCARdS&quot; folder in HA&#39;s native media browser (auto-discovered, no explicit wiring)</td></tr><tr><td><code>storage.py</code></td><td><code>LCARdSStorage</code>: HA Store-backed flat key/value persistence (<code>.storage/lcards</code>)</td></tr><tr><td><code>services.py</code></td><td>Registers the <code>lcards.*</code> HA action namespace: 16 services covering alert modes, frontend control, screen effects, sound, portal overlays, and the Borg Easter egg</td></tr><tr><td><code>services.yaml</code></td><td>Action descriptions and field selectors shown in Developer Tools → Actions</td></tr><tr><td><code>const.py</code></td><td>Shared constants: <code>DOMAIN</code>, <code>DOMAIN_VERSION</code>, option keys, <code>_LOG_LEVEL_MAP</code></td></tr><tr><td><code>manifest.json</code></td><td>HACS/HA integration manifest: domain, version (HA CalVer), dependencies</td></tr><tr><td><code>strings.json</code> + <code>translations/en.json</code></td><td>UI strings for the config and options dialog</td></tr></tbody></table><hr><h2 id="boot-sequence" tabindex="-1">Boot Sequence <a class="header-anchor" href="#boot-sequence" aria-label="Permalink to &quot;Boot Sequence&quot;">​</a></h2><p>HA calls the integration in two phases:</p><h3 id="phase-1-async-setup-ha-start-before-config-entry" tabindex="-1">Phase 1: <code>async_setup()</code> (HA start, before config entry) <a class="header-anchor" href="#phase-1-async-setup-ha-start-before-config-entry" aria-label="Permalink to &quot;Phase 1: `async_setup()` (HA start, before config entry)&quot;">​</a></h3><p>Runs at HA startup before any config entry is loaded. Registers infrastructure that must be available immediately:</p><ol><li><strong>Static paths</strong> (via <code>frontend.py</code>), single directory registration: <ul><li><code>/lcards/</code> → <code>custom_components/lcards/</code> (serves bundle, source map, and all asset subdirectories)</li></ul></li><li><strong>WebSocket commands</strong>: <code>lcards/info</code> registered so the JS probe works even before setup</li></ol><h3 id="phase-2-async-setup-entry-config-entry-active" tabindex="-1">Phase 2: <code>async_setup_entry()</code> (config entry active) <a class="header-anchor" href="#phase-2-async-setup-entry-config-entry-active" aria-label="Permalink to &quot;Phase 2: `async_setup_entry()` (config entry active)&quot;">​</a></h3><p>Runs when the integration is configured (after initial setup or on restart):</p><ol><li><strong>Log level</strong>: maps the <code>log_level</code> option to a Python <code>logging</code> level and calls <code>setLevel()</code> on the <code>custom_components.lcards</code> parent logger, cascading to all child loggers</li><li><strong>Storage init</strong>: creates <code>LCARdSStorage</code>, loads <code>.storage/lcards</code> from disk, stores the instance at <code>hass.data[&quot;lcards&quot;][&quot;storage&quot;]</code></li><li><strong>Services</strong>: <code>async_setup_services(hass)</code> registers the full <code>lcards.*</code> action namespace (16 services)</li><li><strong>JS injection</strong>: <code>add_extra_js_url</code> loads <code>lcards.js?v=...&amp;log=&lt;level&gt;</code> on every HA page; the <code>?log=</code> param lets <code>lcards.js</code> read the configured level at module load time via <code>import.meta.url</code></li><li><strong>Lovelace resource</strong>: registers the script for Cast / kiosk support</li><li><strong>Sidebar panel</strong>: <code>async_register_built_in_panel</code> with the configured title and icon, if <code>show_panel</code> option is <code>True</code></li><li><strong>Options listener</strong>: <code>entry.add_update_listener()</code> triggers an entry reload when the user saves new options, applying changes without an HA restart</li></ol><h3 id="unload-async-unload-entry" tabindex="-1">Unload: <code>async_unload_entry()</code> <a class="header-anchor" href="#unload-async-unload-entry" aria-label="Permalink to &quot;Unload: `async_unload_entry()`&quot;">​</a></h3><p>Called on HA restart, explicit reload (triggered by options change), or removal:</p><ol><li><strong>Services</strong>: <code>async_remove_services(hass)</code> deregisters all <code>lcards.*</code> services</li><li>Removes <code>add_extra_js_url</code> injection</li><li>Removes the Lovelace resource</li><li>Removes the sidebar panel</li></ol><p><code>async_remove_entry()</code> is a no-op; <code>async_unload_entry</code> handles all cleanup.</p><hr><h2 id="static-paths" tabindex="-1">Static Paths <a class="header-anchor" href="#static-paths" aria-label="Permalink to &quot;Static Paths&quot;">​</a></h2><p>A single directory registration serves the entire <code>custom_components/lcards/</code> directory:</p><table tabindex="0"><thead><tr><th>URL path</th><th>Serves</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/lcards/lcards.js</code></td><td><code>lcards.js</code></td><td>Main JS bundle: loaded by <code>add_extra_js_url</code></td></tr><tr><td><code>/lcards/lcards.js.map</code></td><td><code>lcards.js.map</code></td><td>Source map for browser devtools stack traces</td></tr><tr><td><code>/lcards/fonts/*</code></td><td><code>fonts/</code></td><td>LCARS typography assets</td></tr><tr><td><code>/lcards/sounds/*</code></td><td><code>sounds/</code></td><td>Bundled audio packs</td></tr><tr><td><code>/lcards/msd/*</code></td><td><code>msd/</code></td><td>Ship SVG files for MSD cards</td></tr><tr><td><code>/lcards/images/*</code></td><td><code>images/</code></td><td>Built-in image library</td></tr><tr><td><code>/lcards/brand/*</code></td><td><code>brand/</code></td><td>Brand icons and graphics</td></tr></tbody></table><p>All asset URLs in the JS bundle reference the <code>/lcards/</code> prefix, which maps directly to <code>custom_components/lcards/</code> via the integration&#39;s static path registration.</p><hr><h2 id="media-source-platform" tabindex="-1">Media Source Platform <a class="header-anchor" href="#media-source-platform" aria-label="Permalink to &quot;Media Source Platform&quot;">​</a></h2><p><code>media_source.py</code> exposes the bundled <code>images/</code> and <code>sounds/</code> directories as a browsable, read-only <strong>&quot;LCARdS&quot;</strong> folder inside Home Assistant&#39;s native media browser: the Media sidebar panel, any media-picker dialog, and every <code>ha-selector</code> of type <code>media</code> (including the ones LCARdS&#39;s own editors use, see <a href="./subsystems/asset-manager.html#media-source-resolution-flow">Asset Manager: media-source:// Resolution Flow</a>).</p><p><strong>Discovery is automatic and requires no explicit registration call</strong>: HA&#39;s <code>media_source</code> integration scans every loaded integration for a <code>media_source.py</code> module exposing <code>async_get_media_source(hass)</code> (via <code>homeassistant.helpers.integration_platform.async_process_integration_platforms</code>), which sets <code>hass.data[MEDIA_SOURCE_DATA][&quot;lcards&quot;]</code>. No <code>manifest.json</code> dependency is strictly required for discovery; LCARdS declares <code>&quot;after_dependencies&quot;: [&quot;media_source&quot;]</code> defensively, purely to order its own setup after <code>media_source</code>&#39;s HTTP views/WS commands are ready.</p>',25)),(a(),r(n,null,{default:d(()=>[c(s,{id:"mermaid-337",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Discover%5B%22media_source%20integration%5Cnasync_process_integration_platforms()%22%5D%20--%3E%7C%22finds%20media_source.py%22%7C%20Get%5B%22async_get_media_source(hass)%22%5D%0A%20%20%20%20Get%20--%3E%20Src%5B%22LCARdSMediaSource%22%5D%0A%20%20%20%20Src%20--%3E%7C%22async_browse_media()%22%7C%20Browse%5B%22Browse%20tree%3A%5CnLCARdS%20%E2%86%92%20Images%2FSounds%20%E2%86%92%20files%22%5D%0A%20%20%20%20Src%20--%3E%7C%22async_resolve_media()%22%7C%20Resolve%5B%22PlayMedia(url%3D'%2Flcards%2F...')%22%5D%0A%20%20%20%20Resolve%20--%3E%7C%22reuses%22%7C%20StaticPath%5B%22existing%20%2Flcards%20static%20path%5Cn(frontend.py)%22%5D%0A"})]),fallback:d(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=i('<p><code>LCARdSMediaSource</code> (extends <code>MediaSource</code>) is deliberately simple and read-only: no upload/delete machinery, unlike HA core&#39;s <code>local_source.py</code>:</p><ul><li><strong><code>async_browse_media()</code></strong> walks the two allowed root directories (<code>images/</code>, <code>sounds/</code>) one level at a time, mapping each file&#39;s identifier to its path relative to <code>custom_components/lcards/</code> (e.g. <code>images/bedroom.jpg</code>, <code>sounds/lcards_alerts/alert_klaxon_1.mp3</code>). Only <code>image/*</code> and <code>audio/*</code> MIME types are surfaced (via <code>mimetypes.guess_type</code>).</li><li><strong><code>async_resolve_media()</code></strong> does <strong>not</strong> serve files itself; it returns <code>PlayMedia(url=f&quot;/lcards/{identifier}&quot;, ...)</code>, pointing straight at the static path <code>frontend.py</code> already registers. No new HTTP view is needed.</li><li>Path-traversal is guarded by resolving the requested identifier and checking it stays under the integration&#39;s own directory (<code>Path.relative_to()</code>), mirroring the check in HA core&#39;s <code>local_source.py</code>.</li></ul><p>This is intentionally scoped to LCARdS&#39;s own <strong>bundled, read-only</strong> assets. It does not expose user-uploaded or <code>/local/</code>-registered images; those already live in HA&#39;s own <code>media_source.local</code> tree.</p><hr><h2 id="config-options-flow" tabindex="-1">Config &amp; Options Flow <a class="header-anchor" href="#config-options-flow" aria-label="Permalink to &quot;Config &amp; Options Flow&quot;">​</a></h2><p>LCARdS enforces a single-instance constraint (<code>async_set_unique_id(DOMAIN)</code>). The initial setup form requires no user input; clicking through is sufficient.</p><p>After setup, users configure options via <strong>Settings → Integrations → LCARdS → Configure</strong>:</p><table tabindex="0"><thead><tr><th>Option key</th><th><code>const.py</code> constant</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>show_panel</code></td><td><code>CONF_SHOW_PANEL</code></td><td><code>True</code></td><td>Register or remove the sidebar panel</td></tr><tr><td><code>sidebar_title</code></td><td><code>CONF_SIDEBAR_TITLE</code></td><td><code>&quot;LCARdS Config&quot;</code></td><td>Sidebar label text</td></tr><tr><td><code>sidebar_icon</code></td><td><code>CONF_SIDEBAR_ICON</code></td><td><code>&quot;mdi:space-invaders&quot;</code></td><td>Sidebar icon (MDI name)</td></tr><tr><td><code>log_level</code></td><td><code>CONF_LOG_LEVEL</code></td><td><code>&quot;warn&quot;</code></td><td>Frontend + backend verbosity: see <a href="#logging">Logging</a> below</td></tr></tbody></table><p>All changes applied immediately via entry reload, no HA restart required.</p><hr><h2 id="websocket-api" tabindex="-1">WebSocket API <a class="header-anchor" href="#websocket-api" aria-label="Permalink to &quot;WebSocket API&quot;">​</a></h2><p>The integration registers WebSocket commands under the <code>lcards/*</code> namespace via <code>websocket_api.py</code>. Commands registered in <code>async_setup()</code> (before the config entry) are available immediately after HA start.</p><h3 id="lcards-subscribe" tabindex="-1"><code>lcards/subscribe</code> <a class="header-anchor" href="#lcards-subscribe" aria-label="Permalink to &quot;`lcards/subscribe`&quot;">​</a></h3><p>Non-admin push-channel subscription, registered in <code>async_setup()</code>. Clients subscribe once and receive <code>lcards_event</code> bus events forwarded as WS event messages. This replaces the HA-native <code>subscribeEvents</code> API for this purpose, which is restricted to admin users for custom event types.</p><table tabindex="0"><thead><tr><th>Command</th><th>Registered</th><th>Response</th></tr></thead><tbody><tr><td><code>lcards/subscribe</code></td><td><code>async_setup()</code></td><td><code>{}</code> result immediately, then event messages as <code>lcards_event</code> fires</td></tr></tbody></table><p>Used by <code>IntegrationService</code> after a successful <code>lcards/info</code> probe. → See <a href="./subsystems/integration-service.html#push-channel">Integration Service: Push Channel</a>.</p><h3 id="lcards-info" tabindex="-1"><code>lcards/info</code> <a class="header-anchor" href="#lcards-info" aria-label="Permalink to &quot;`lcards/info`&quot;">​</a></h3><p>Backend probe, registered in <code>async_setup()</code> so it is always available.</p><table tabindex="0"><thead><tr><th>Command</th><th>Registered</th><th>Response</th></tr></thead><tbody><tr><td><code>lcards/info</code></td><td><code>async_setup()</code></td><td><code>{ available: true, version: &quot;...&quot; }</code></td></tr></tbody></table><p>Used by <code>IntegrationService</code> on the JS side to detect backend presence. → See <a href="./subsystems/integration-service.html">Integration Service</a>.</p><h3 id="lcards-storage" tabindex="-1"><code>lcards/storage/*</code> <a class="header-anchor" href="#lcards-storage" aria-label="Permalink to &quot;`lcards/storage/*`&quot;">​</a></h3><p>Persistent key/value store, registered in <code>async_setup()</code>, but requires the storage instance (initialised in <code>async_setup_entry()</code>) to respond.</p><table tabindex="0"><thead><tr><th>Command</th><th>Parameters</th><th>Response</th></tr></thead><tbody><tr><td><code>lcards/storage/get</code></td><td><code>key?: string</code></td><td><code>{ key, value }</code>: value is <code>null</code> for missing key</td></tr><tr><td><code>lcards/storage/set</code></td><td><code>data: { [key]: value }</code></td><td><code>{ ok: true, keys: [...] }</code></td></tr><tr><td><code>lcards/storage/delete</code></td><td><code>key: string</code></td><td><code>{ ok: true, existed: bool }</code></td></tr><tr><td><code>lcards/storage/reset</code></td><td>-</td><td><code>{ ok: true }</code></td></tr><tr><td><code>lcards/storage/dump</code></td><td>-</td><td><code>{ version: 1, data: { ... } }</code></td></tr></tbody></table><p>→ Full reference including browser console test snippets: <a href="./internals/storage.html">Persistent Storage</a>.</p><hr><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>All integration Python files use <code>logging.getLogger(__name__)</code>; the logger hierarchy is <code>custom_components.lcards.*</code>.</p><p>The <code>log_level</code> option controls <strong>both</strong> frontend and backend verbosity:</p><ul><li><strong>Frontend</strong>: <code>log_level</code> is appended as <code>?log=&lt;level&gt;</code> to the <code>add_extra_js_url</code> script URL. <code>lcards.js</code> reads it from <code>import.meta.url</code> at module load time (before the banner). The page URL parameter <code>?lcards_log_level=</code> overrides it for the current session.</li><li><strong>Backend</strong>: <code>async_setup_entry()</code> maps the level string to a Python <code>logging</code> level via <code>_LOG_LEVEL_MAP</code> and calls <code>setLevel()</code> on <code>custom_components.lcards</code>, cascading to all child loggers.</li></ul><table tabindex="0"><thead><tr><th>lcards level</th><th>Python level</th></tr></thead><tbody><tr><td><code>off</code></td><td><code>CRITICAL + 1</code> (effectively silent)</td></tr><tr><td><code>error</code></td><td><code>ERROR</code></td></tr><tr><td><code>warn</code></td><td><code>WARNING</code></td></tr><tr><td><code>info</code></td><td><code>INFO</code></td></tr><tr><td><code>debug</code></td><td><code>DEBUG</code></td></tr><tr><td><code>trace</code></td><td><code>DEBUG</code></td></tr></tbody></table><p>You can also override the Python log level independently via <code>configuration.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">logger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  logs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    custom_components.lcards</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">debug</span></span></code></pre></div><hr><h2 id="ha-services-actions" tabindex="-1">HA Services (Actions) <a class="header-anchor" href="#ha-services-actions" aria-label="Permalink to &quot;HA Services (Actions)&quot;">​</a></h2><p>The integration registers a <code>lcards.*</code> action namespace in <code>async_setup_entry()</code>, handled by <code>services.py</code>, 16 services in total.</p><table tabindex="0"><thead><tr><th>Service</th><th>Parameters</th><th>Effect</th></tr></thead><tbody><tr><td><code>lcards.set_alert_mode</code></td><td><code>mode: string</code></td><td>Sets <code>input_select.lcards_alert_mode</code> to the supplied mode (or fires a targeted event if targeting fields are given)</td></tr><tr><td><code>lcards.red_alert</code></td><td>-</td><td>Sets alert mode to <code>red_alert</code></td></tr><tr><td><code>lcards.yellow_alert</code></td><td>-</td><td>Sets alert mode to <code>yellow_alert</code></td></tr><tr><td><code>lcards.blue_alert</code></td><td>-</td><td>Sets alert mode to <code>blue_alert</code></td></tr><tr><td><code>lcards.gray_alert</code></td><td>-</td><td>Sets alert mode to <code>gray_alert</code></td></tr><tr><td><code>lcards.black_alert</code></td><td>-</td><td>Sets alert mode to <code>black_alert</code></td></tr><tr><td><code>lcards.clear_alert</code></td><td>-</td><td>Sets alert mode to <code>green_alert</code> (normal)</td></tr><tr><td><code>lcards.reload</code></td><td>-</td><td>Fires <code>lcards_event {action: reload}</code> to connected browser tabs</td></tr><tr><td><code>lcards.set_log_level</code></td><td><code>level: string</code></td><td>Updates Python loggers + fires <code>lcards_event {action: set_log_level}</code></td></tr><tr><td><code>lcards.trigger_effect</code></td><td><code>layers: dict</code>, <code>duration?: int</code></td><td>Fires a full-screen effect (backdrop/color/canvas layers) via the push channel</td></tr><tr><td><code>lcards.clear_effect</code></td><td><code>slot?: string</code></td><td>Clears active screen effect(s); omit <code>slot</code> to clear all</td></tr><tr><td><code>lcards.play_sound</code></td><td><code>event_type?: string</code>, <code>asset_key?: string</code></td><td>Plays a sound effect on target frontends</td></tr><tr><td><code>lcards.show_portal_card</code></td><td><code>content: dict</code>, <code>layers?</code>, <code>position?</code>, <code>width?</code>, <code>height?</code>, <code>duration?</code>, <code>dismiss?</code></td><td>Shows a portal card overlay via <code>PortalOverlayManager</code> (slot <code>&#39;ha-service&#39;</code>)</td></tr><tr><td><code>lcards.clear_portal_card</code></td><td>-</td><td>Clears the <code>&#39;ha-service&#39;</code> portal overlay</td></tr><tr><td><code>lcards.borg_assimilate</code></td><td><code>intro_duration?</code>, <code>transition_style?</code>, <code>site_count?</code>, <code>tendrils_per_site?</code>, <code>tendril_length?</code>, <code>particle_count?</code>, <code>intro_layers?</code>, <code>persistent_layers?</code>, <code>suppress_persistent?</code>, <code>font_swap?</code></td><td>Easter egg: triggers the Borg palette-swap + canvas intro sequence</td></tr><tr><td><code>lcards.borg_deassimilate</code></td><td><code>with_outro?</code>, <code>outro_layers?</code>, <code>revert_transition_style?</code></td><td>Easter egg: reverses <code>borg_assimilate</code>, restoring normal state</td></tr></tbody></table><h3 id="targeting-all-services" tabindex="-1">Targeting (all services) <a class="header-anchor" href="#targeting-all-services" aria-label="Permalink to &quot;Targeting (all services)&quot;">​</a></h3><p>Every service accepts four optional targeting fields, resolved server-side and combinable:</p><table tabindex="0"><thead><tr><th>Field</th><th>Resolves to</th></tr></thead><tbody><tr><td><code>target_device_ids</code></td><td>Browser device UUIDs (as stored in the <code>lcards_device_id</code> localStorage key), used as-is</td></tr><tr><td><code>target_device_names</code></td><td>Device display names (set in the LCARdS config panel or <code>?lcards_device=</code> URL param), matched case-insensitively against LCARdS backend storage; non-unique names hit every matching device</td></tr><tr><td><code>target_user_ids</code></td><td>HA user IDs: used as-is</td></tr><tr><td><code>target_user_names</code></td><td>HA user display names: matched case-insensitively against HA auth</td></tr></tbody></table><p>When none are supplied, a service broadcasts to all connected frontends (or, for the alert-mode services, writes the shared <code>input_select.lcards_alert_mode</code>; see below). When any are supplied, the service instead fires a targeted <code>lcards_event</code>; each JS client self-filters on its own device/user identity.</p><p>Alert mode services delegate to <code>input_select.select_option</code> on <code>input_select.lcards_alert_mode</code> <strong>only when no targeting fields are given</strong>; this fires the full LCARdS pipeline (ThemeManager, SoundManager, alert overlays) via the existing HelperManager subscriptions in JS, with no separate JS wiring required. When targeting fields <em>are</em> given, the shared helper is left untouched (global state must not change) and a targeted <code>set_alert_mode</code> event is fired instead, applied as a transient, non-persistent state change on matching devices only.</p><p>Schema validation is handled by <code>voluptuous</code>; invalid values are rejected before the handler fires. If <code>input_select.lcards_alert_mode</code> doesn&#39;t exist, a <code>WARNING</code> is logged and the service exits without raising.</p><p>→ Full reference including automation examples: <a href="./internals/ha-services.html">HA Services</a></p><hr><h2 id="python-→-js-push-channel" tabindex="-1">Python → JS Push Channel <a class="header-anchor" href="#python-→-js-push-channel" aria-label="Permalink to &quot;Python → JS Push Channel&quot;">​</a></h2><p>Nine services (<code>reload</code>, <code>set_log_level</code>, <code>trigger_effect</code>, <code>clear_effect</code>, <code>play_sound</code>, <code>show_portal_card</code>, <code>clear_portal_card</code>, <code>borg_assimilate</code>, <code>borg_deassimilate</code>) always push instructions directly to connected browser tabs via <code>_fire_targeted_event()</code>, without a page reload or WS request/response cycle. The 7 alert-mode services (<code>set_alert_mode</code>, <code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>, <code>clear_alert</code>) use the same channel only when a targeting field is supplied; otherwise they write directly to <code>input_select.lcards_alert_mode</code> instead (see <a href="#targeting-all-services">Targeting</a> above).</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3>',47)),(a(),r(n,null,{default:d(()=>[c(s,{id:"mermaid-974",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Auto%20as%20Automation%20%2F%20Developer%20Tools%0A%20%20%20%20participant%20PY%20as%20services.py%0A%20%20%20%20participant%20Bus%20as%20HA%20Event%20Bus%0A%20%20%20%20participant%20WS%20as%20websocket_api.py%20(ws_subscribe)%0A%20%20%20%20participant%20JS%20as%20IntegrationService%20(JS)%0A%0A%20%20%20%20Auto-%3E%3EPY%3A%20lcards.reload%0A%20%20%20%20PY-%3E%3EBus%3A%20async_fire(%22lcards_event%22%2C%20%7Baction%3A%20%22reload%22%7D)%0A%20%20%20%20Bus--%3E%3EWS%3A%20_forward%20callback%20fires%0A%20%20%20%20WS--%3E%3EJS%3A%20event_message(%7Baction%3A%20%22reload%22%7D)%0A%20%20%20%20JS-%3E%3EJS%3A%20window.location.reload()%0A"})]),fallback:d(()=>[...e[2]||(e[2]=[o(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=i(`<h3 id="event-payload-shapes" tabindex="-1">Event payload shapes <a class="header-anchor" href="#event-payload-shapes" aria-label="Permalink to &quot;Event payload shapes&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>action</code></th><th>Additional fields</th><th>JS handler (<code>IntegrationService._handleLcardsEvent</code>)</th></tr></thead><tbody><tr><td><code>reload</code></td><td>-</td><td><code>window.location.reload()</code></td></tr><tr><td><code>set_log_level</code></td><td><code>level: string</code></td><td><code>window.lcards.setGlobalLogLevel(level)</code></td></tr><tr><td><code>set_alert_mode</code></td><td><code>mode: string</code></td><td><code>window.lcards.setAlertMode(mode, { skipHelperSync: true })</code>: targeted alert changes only; never fired as a broadcast</td></tr><tr><td><code>trigger_effect</code></td><td><code>layers: object</code>, <code>duration?: number</code></td><td><code>screenEffectManager.applySlot(...)</code> per layer; auto-clears after <code>duration</code></td></tr><tr><td><code>clear_effect</code></td><td><code>slot?: string</code></td><td><code>screenEffect.clearSlot(slot)</code> or <code>.clear()</code> if <code>slot</code> omitted</td></tr><tr><td><code>play_sound</code></td><td><code>event_type?: string</code>, <code>asset_key?: string</code></td><td><code>soundManager.play(event_type)</code> or <code>.playAsset(asset_key)</code></td></tr><tr><td><code>show_portal_card</code></td><td><code>content, layers?, position?, width?, height?, duration?, dismiss?</code></td><td><code>portalOverlayManager.show(&#39;ha-service&#39;, {...})</code></td></tr><tr><td><code>clear_portal_card</code></td><td>-</td><td><code>portalOverlayManager.hide(&#39;ha-service&#39;)</code></td></tr><tr><td><code>borg_assimilate</code></td><td><code>intro_duration?, transition_style?, intro_layers?, persistent_layers?, ...</code></td><td><code>borgAssimilationManager.assimilate(opts)</code></td></tr><tr><td><code>borg_deassimilate</code></td><td><code>with_outro?, outro_layers?, revert_transition_style?</code></td><td><code>borgAssimilationManager.deassimilate(opts)</code></td></tr></tbody></table><h3 id="subscription-lifecycle" tabindex="-1">Subscription lifecycle <a class="header-anchor" href="#subscription-lifecycle" aria-label="Permalink to &quot;Subscription lifecycle&quot;">​</a></h3><p><code>IntegrationService</code> subscribes via the <code>lcards/subscribe</code> WS command <strong>after</strong> the <code>lcards/info</code> probe succeeds, so the push channel is only open when the backend is confirmed active. This command is non-admin-gated, so all users (including non-admin dashboards) receive push events:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async_setup_entry → backend online → IntegrationService.initialize() succeeds</span></span>
<span class="line"><span>    → _startEventListener() → hass.connection.subscribeMessage(handler, { type: &#39;lcards/subscribe&#39; })</span></span>
<span class="line"><span>        → stores unsub fn as _eventUnsubscribe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async_unload_entry → integration unloaded (tab navigates away / WS closes)</span></span>
<span class="line"><span>    → WebSocket disconnect → subscription cleaned up automatically</span></span></code></pre></div><p>On the Python side, <code>ws_subscribe</code> registers a <code>@callback</code>-decorated listener on the HA event bus for <code>lcards_event</code>. When the event fires, it forwards <code>event.data</code> directly to the WS connection via <code>connection.send_message(event_message(...))</code>. The <code>@callback</code> decorator ensures the forward runs on the event loop thread, not in an executor.</p><p>Transport is always a <strong>broadcast</strong>: every open tab subscribed via <code>lcards/subscribe</code> receives every event. Targeting (<code>target_device_ids</code> / <code>target_device_names</code> / <code>target_user_ids</code> / <code>target_user_names</code>) is enforced client-side: each <code>IntegrationService</code> checks the event&#39;s target lists against its own device/user identity and silently drops events not addressed to it. Events with no target lists (the default) are acted on by every tab.</p><p>→ JS implementation details: <a href="./subsystems/integration-service.html#push-channel">Integration Service: Push Channel</a></p><hr><h2 id="build-dev-workflow" tabindex="-1">Build &amp; Dev Workflow <a class="header-anchor" href="#build-dev-workflow" aria-label="Permalink to &quot;Build &amp; Dev Workflow&quot;">​</a></h2><p>The integration build outputs directly into <code>custom_components/lcards/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:integration</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># = vite build --mode integration &amp;&amp; node scripts/copy-assets.js</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Outputs:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   custom_components/lcards/lcards.js</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   custom_components/lcards/lcards.js.map</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   custom_components/lcards/fonts/   (from src/assets/fonts/)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   custom_components/lcards/msd/     (from src/assets/msd/)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   custom_components/lcards/sounds/  (from src/assets/sounds/)</span></span></code></pre></div><p>In the devcontainer, <code>custom_components/lcards/</code> is bind-mounted into the HA core workspace, so a build is picked up immediately. A browser hard-refresh (<code>Ctrl+Shift+R</code>) applies JS changes; Python changes require a full HA restart.</p><hr><h2 id="ci-release-pipeline" tabindex="-1">CI / Release Pipeline <a class="header-anchor" href="#ci-release-pipeline" aria-label="Permalink to &quot;CI / Release Pipeline&quot;">​</a></h2><p>The <code>release.yml</code> GitHub Actions workflow handles versioning and packaging:</p><ol><li><code>workflow_dispatch</code>, run manually against the desired branch, triggers the workflow</li><li>Version (<code>YYYY.MM.SEQ[-dev.N]</code>, read from <code>package.json</code>; sequence resets each month) is normalised to HA CalVer (no leading zeros, no pre-release suffix) and stamped into <code>manifest.json</code>; the full version string (including any <code>-dev.N</code> suffix) is kept in <code>const.py</code></li><li><code>npm run build:integration</code> produces the complete integration directory</li><li><code>custom_components/lcards/</code> is zipped as <code>lcards.zip</code> (excluding <code>__pycache__</code>, <code>.pyc</code>)</li><li>A GitHub release is created with the zip attached</li></ol><p>HACS downloads this zip and extracts it into <code>custom_components/lcards/</code> on the user&#39;s HA instance.</p>`,18))])}const k=l(u,[["render",g]]);export{A as __pageData,k as default};
